head.script:
scwin.test = function() {
    $w.log("main" + "_initScript");
}
scwin.test2 = function() {
    $w.log("main" + "_initScript2");
}
scwin.post1 = function() {
    $w.log("main" + "_postScript1");
}
scwin.post2 = function() {
    $w.log("main" + "_postScript2");
}
scwin.onpageload = function() {
    $w.log("main" + "_onpageload");
    if (console.log) {
        console.log("main" + "_onpageload");
    }
}
scwin.__showLogInStep = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("STEP7") < log.indexOf("w2_initScript2");
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 
    //1. Check the sample executable in main.xml and the developer mode (F12) console and check ctrl + right-click> log view.
    // verify step 1. 로그보기의 initScript, postScript의 실행순서가 STEP7에서 실행되어진다.(이전에는 STEP3에서 실행되어짐. 실행순서 변경됨)
    //1. The execution order of initScript and postScript in log view is executed in STEP7.(Previously executed in STEP3, execution order changed)
    WebSquare.wUnit.addCommand("assert", "scwin.__showLogInStep()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 20-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
